(48363, 'ptBR', 'Ordem de Serviço: Malaquita Florida', '', '', '', '', '', '', '', '', 25549),
(48360, 'ptBR', 'Suprimentos necessários: Couro Bestial', '', '', '', '', '', '', '', '', 25549),
(48359, 'ptBR', 'Ordem de Serviço: Couro Bestial', '', '', '', '', '', '', '', '', 25549),
(48358, 'ptBR', 'Suprimento necessário: Empirita', '', '', '', '', '', '', '', '', 25549),
(48349, 'ptBR', 'Ordem de Serviço: Empirita', '', '', '', '', '', '', '', '', 25549),
(48345, 'ptBR', 'Forças de Talgath', 'Mate 12 das forças de Talgath.', 'Preciso ir atrás do Brasão do Conhecimento, $Gmeu caro:minha cara. A Coroa do Triunvirato é a única coisa capaz de mudar o rumo dessa batalha.$b$bAs forças de Talgath estão no nosso caminho até ela. Preciso que tu nos abras caminho.$b$bNinguém pode nos deter. Nem mesmo Talgath.', '', '', '', '', '', '', 25549),
(48344, 'ptBR', 'Problema à vista', 'Fale com Turalyon no Conservatório do Arcano.', 'Estamos com um problema, $n. A Legião chegou a Mac''Aree.$b$bAssim que você recuperou o Signo, foi como se tivessem anunciado a nossa presença por toda Argus. Os olhos de Antorus estão fixados na gente.$b$bCalma, fica muito pior.$b$bVelen foi com a capitã Fareeya e suas forças para os Jardins de Arinor em busca do Brasão do Conhecimento. Pelo que me disseram, agora estão atrás das linhas inimigas.$b$bAcompanhe-me até o Conservatório. Temos que trazê-los de volta antes que seja tarde demais.', '', '', '', '', '', '', 25549),
(48338, 'ptBR', 'Suprimento necessário: Glória-astral', '', '', '', '', '', '', '', '', 25549),
(48337, 'ptBR', 'Ordem de Serviço: Glória-astral', '', '', '', '', '', '', '', '', 25549),
(48323, 'ptBR', 'Ordem de Serviço: Lágrimas dos Naaru', '', '', '', '', '', '', '', '', 25549),
(48318, 'ptBR', 'Ordem de Serviço: Elixires de Sangue Leve', '', '', '', '', '', '', '', '', 25549),
(48305, 'ptBR', 'O conciliábulo ardente', 'Derrote o Conciliábulo de Shivarra em Antorus, o Trono Ardente.', 'Nem mesmo um Titã suporta a tortura delas. Ponha fim no Conciliábulo de Shivarra.', '', '', '', '', '', '', 25549),
(48304, 'ptBR', 'O caçador de almas', 'Derrotar Imonar, o Caçador de Almas, em Antorus, o Trono Ardente.', 'Imonar é o caçador de recompensas mais perigoso que já saiu da Espiral Etérea. Vá sacudir o corpo dele numa cova.', '', '', '', '', '', '', 25549),
(48303, 'ptBR', 'Alto Comando Antorano', 'Derrotar o Alto Comando Antorano em Antorus, o Trono Ardente.', 'A Legião passou 10.000 anos planejando a invasão a Azeroth. Derrote os líderes deles para que nunca voltem a ameaçar o nosso mundo.', '', '', '', '', '', '', 25549),
(48301, 'ptBR', 'O conciliábulo ardente', 'Derrote o Conciliábulo de Shivarra em Antorus, o Trono Ardente.', 'Nem mesmo um Titã suporta a tortura delas. Ponha fim no Conciliábulo de Shivarra.', '', '', '', '', '', '', 25549),
(48300, 'ptBR', 'O caçador de almas', 'Derrotar Imonar, o Caçador de Almas, em Antorus, o Trono Ardente.', 'Imonar é o caçador de recompensas mais perigoso que já saiu da Espiral Etérea. Vá sacudir o corpo dele numa cova.', '', '', '', '', '', '', 25549),
(48299, 'ptBR', 'Alto Comando Antorano', 'Derrotar o Alto Comando Antorano em Antorus, o Trono Ardente.', 'A Legião passou 10.000 anos arquitetando a invasão a Azeroth. Derrote os líderes deles para que nunca voltem a ameaçar o nosso mundo.', '', '', '', '', '', '', 25549),
(48297, 'ptBR', 'O conciliábulo ardente', 'Derrote o Conciliábulo de Shivarra em Antorus, o Trono Ardente.', 'Nem mesmo um Titã suporta a tortura delas. Ponha fim no Conciliábulo de Shivarra.', '', '', '', '', '', '', 25549),
