UPDATE `quest_template_locale` SET `LogDescription`='Obtenha o Núcleo Infernal de Kroshius.', `QuestDescription`='O mais temível demônio do Vale das Escaras Pungentes é conhecido como Kroshius. Apesar de muitos o terem caçado ao longo dos anos, os ataques apenas o fortaleceram.$B$BUm após o outro, bruxos vieram a esta floresta e reanimaram Kroshius. E hoje ele espreita a sudeste, cercado por fogo demoníaco, aguardando qualquer um que tente reclamar o poder dele.$B$BNão permitirei que este ciclo infernal continue! Mate Kroshius e traga-me seu núcleo infernal.', `PortraitGiverText`='Tomar o âmago dele destruirá este ciclo.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=28359 AND `locale`='ptBR');
