UPDATE `quest_template_locale` SET `QuestDescription`='<O console de comunicação emite um zumbido.>$B$BOs worgens que você matou eram do grupo de batedores. Tem centenas mais se aproximando! Parece que Crowley e Dentessangue fizeram a oferta de sangue para cada humano de Lordaeron.$B$BSuba num dos canhões da Horda e mande-os encontrar o criador. Que as águas do Espelho de Lordaeron fiquem rubras com o sangue deles!', `PortraitGiverText`='As águas do Espelho de Lordaeron se tingirão de vermelho com o sangue dos worgens!', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=27232 AND `locale`='ptBR');
